#!/usr/bin/env python3
"""Generates src/sin_lut.v: L[a] = round(1024*sin(a deg)), a = 0..90 (unsigned 11-bit).
1024 = 64 steps * 16: 64 phase steps (of 2.8125 deg) is pi, the element-to-element phase at
half-wavelength spacing for sin(theta)=1, with 4 fractional bits."""
import math, pathlib
rows = "\n".join(f"            7'd{a}: lut = 11'd{round(1024*math.sin(math.radians(a)))};" for a in range(91))
v = f"""`default_nettype none
// Generated by tools/gen_sin_lut.py - do not edit by hand.
module sin_lut (
    input  wire [6:0]  deg,     // 0..90
    output reg  [10:0] lut      // round(1024*sin(deg))
);
    always @(*) begin
        case (deg)
{rows}
            default: lut = 11'd1024;
        endcase
    end
endmodule
"""
pathlib.Path(__file__).resolve().parent.parent.joinpath("src", "sin_lut.v").write_text(v)
